$$
\begin{align*}
max_{n \in [N]} \max_\pi \left(V_{\theta_n^*,\,R_n}^{\pi} - V_{\theta_n^*,\,R_n}^{\bar{\pi}^n}\right) \le \epsilon.
\end{align*}
$$

